package test

import (
	. "github.com/onsi/ginkgo/v2"

	. "github.com/ArtHustle/mock_gen"
)

// --add-header-note prepends the standard "Code generated by MockGen.
// DO NOT EDIT." comment. Tested independently to keep flag-combination
// tests focused on their own feature.
var _ = Describe("Header note", func() {
	DescribeTable("emits the expected mock",
		runGenEntry,

		Entry("prefixes the generated-code header", `
package pkg

type Service interface {
	DoSomething()
}`,
			`// Code generated by MockGen. DO NOT EDIT.

package test

type ServiceMock struct {
	DoSomething_calls int
}

func (this *ServiceMock) DoSomething() {
	this.DoSomething_calls++
}
`, Options{AddHeaderNote: true}),
	)
})
